#include "wav_io.hpp"
#include <array>
#include <cstring>
#include <fstream>
namespace {uint16_t u16le(const unsigned char*p){return static_cast<uint16_t>(p[0]|(p[1]<<8));}uint32_t u32le(const unsigned char*p){return static_cast<uint32_t>(p[0]|(p[1]<<8)|(p[2]<<16)|(p[3]<<24));}void put16(std::ofstream&f,uint16_t v){char b[2]{char(v&255),char((v>>8)&255)};f.write(b,2);}void put32(std::ofstream&f,uint32_t v){char b[4]{char(v&255),char((v>>8)&255),char((v>>16)&255),char((v>>24)&255)};f.write(b,4);}}
bool read_wav(const std::string&path,WavData&wav,std::string&error){std::ifstream f(path,std::ios::binary);if(!f){error="cannot open input";return false;}std::array<unsigned char,12>h{};f.read(reinterpret_cast<char*>(h.data()),12);if(!f||std::memcmp(h.data(),"RIFF",4)||std::memcmp(h.data()+8,"WAVE",4)){error="not RIFF/WAVE";return false;}uint16_t format=0,bits=0,channels=0;uint32_t rate=0;std::vector<unsigned char>data;while(f){std::array<unsigned char,8>ch{};f.read(reinterpret_cast<char*>(ch.data()),8);if(!f)break;uint32_t size=u32le(ch.data()+4);std::vector<unsigned char>p(size);f.read(reinterpret_cast<char*>(p.data()),size);if(size&1u)f.get();if(!std::memcmp(ch.data(),"fmt ",4)&&size>=16){format=u16le(p.data());channels=u16le(p.data()+2);rate=u32le(p.data()+4);bits=u16le(p.data()+14);}else if(!std::memcmp(ch.data(),"data",4))data=std::move(p);}if(!channels||!rate||data.empty()){error="missing fmt/data chunk";return false;}uint32_t bytes=bits/8u;if(!bytes)return false;size_t samples=data.size()/bytes;wav.sample_rate=rate;wav.channels=channels;wav.interleaved.resize(samples);if(format==1&&bits==16){for(size_t i=0;i<samples;++i){int16_t v=static_cast<int16_t>(u16le(data.data()+i*2));wav.interleaved[i]=static_cast<float>(v)/32768.0f;}}else if(format==3&&bits==32){for(size_t i=0;i<samples;++i){float v{};std::memcpy(&v,data.data()+i*4,4);wav.interleaved[i]=v;}}else{error="supported input formats: PCM16 or IEEE float32 WAV";return false;}return true;}
bool write_wav_float32(const std::string&path,const WavData&wav,std::string&error){if(!wav.channels||!wav.sample_rate||wav.interleaved.size()%wav.channels)return false;uint32_t db=static_cast<uint32_t>(wav.interleaved.size()*sizeof(float));std::ofstream f(path,std::ios::binary);if(!f){error="cannot open output";return false;}f.write("RIFF",4);put32(f,36u+db);f.write("WAVE",4);f.write("fmt ",4);put32(f,16);put16(f,3);put16(f,wav.channels);put32(f,wav.sample_rate);put32(f,wav.sample_rate*wav.channels*4u);put16(f,static_cast<uint16_t>(wav.channels*4u));put16(f,32);f.write("data",4);put32(f,db);f.write(reinterpret_cast<const char*>(wav.interleaved.data()),static_cast<std::streamsize>(db));return bool(f);}
